# Fractions, not floats: floats once showed '0.30000000000000004 cups' (BUG-12).
import unittest
from fractions import Fraction

from pantry.quantity import kitchen_round, parse_qty
from pantry.scale import scale


class ScalingTest(unittest.TestCase):
    def test_thirds_scale_exactly(self):
        self.assertEqual(scale('1/3', 3), '1')

    def test_mixed_numbers(self):
        self.assertEqual(parse_qty('1 1/2'), Fraction(3, 2))
        self.assertEqual(scale('1 1/2', 2), '3')

    def test_kitchen_rounding_to_eighths(self):
        self.assertEqual(kitchen_round(Fraction(1, 3)), Fraction(3, 8))
import unittest

from pantry.units import volume_ml


class UnitsTest(unittest.TestCase):
    def test_australian_tablespoon(self):
        self.assertEqual(volume_ml('tbsp', 'en-AU'), 20)

    def test_unknown_locale_falls_back_to_metric(self):
        self.assertEqual(volume_ml('cup', 'fr-FR'), 250)

